const b = $('Webhook').first().json.body || {};
if (b.secret !== 'sv-mail-2026-09-17-Kq7') { throw new Error('bad secret'); }
const DRY = b.apply !== true;
const s = (v) => String(v == null ? '' : v).trim();
const vr = $('Get').first().json.valueRanges || [];
const A = (vr[0] || {}).values || [], B = (vr[1] || {}).values || [];
if (A.length < 40 || B.length < 40) { throw new Error('ABORT short read ' + A.length + '/' + B.length); }

// Bon Cuisine. Founder asked for 25 Cr on the Northern Arc call, 4 Sep 2026.
// Both tabs still carry the 20 Cr from July, which is what every outreach
// subject line has been quoting since.
const NAME = 'Bon Cuisine';
const EXPECT_A = 'INR 20 Cr';   // STARTUPS.raise_inr_cr - builds the subject line
const EXPECT_B = '20';          // STARTUP_PROFILE.raise_cr - drives matching
const NEW_A = 'INR 25 Cr';
const NEW_B = '25';

const ha = A[0].map(s), hb = B[0].map(s);
const ai = ha.indexOf('raise_inr_cr'), bi = hb.indexOf('raise_cr');
if (ai < 0 || bi < 0) { throw new Error('ABORT: column missing ' + ai + '/' + bi); }
const arow = A.findIndex((r, i) => i > 0 && s(r[0]).toLowerCase() === NAME.toLowerCase());
const brow = B.findIndex((r, i) => i > 0 && s(r[0]).toLowerCase() === NAME.toLowerCase());
if (arow < 1 || brow < 1) { throw new Error('ABORT: row not found ' + arow + '/' + brow); }
const curA = s((A[arow] || [])[ai]), curB = s((B[brow] || [])[bi]);

// Guard: only overwrite the exact stale value. If someone already corrected it,
// or it says something else entirely, stop rather than clobber their work.
const okA = curA === EXPECT_A, okB = curB === EXPECT_B;
const colL = (i) => { let n = i + 1, t = ''; while (n > 0) { const m = (n - 1) % 26; t = String.fromCharCode(65 + m) + t; n = Math.floor((n - 1) / 26); } return t; };
const data = [];
if (okA) { data.push({ range: 'STARTUPS!' + colL(ai) + (arow + 1), values: [[NEW_A]] }); }
if (okB) { data.push({ range: 'STARTUP_PROFILE!' + colL(bi) + (brow + 1), values: [[NEW_B]] }); }
const report = { dry: DRY, startup: NAME,
  startups_cell: 'STARTUPS!' + colL(ai) + (arow + 1), startups_now: curA, startups_new: okA ? NEW_A : 'SKIPPED - not the expected stale value',
  profile_cell: 'STARTUP_PROFILE!' + colL(bi) + (brow + 1), profile_now: curB, profile_new: okB ? NEW_B : 'SKIPPED - not the expected stale value',
  will_write: data.length };
return [{ json: { report, data: DRY ? [] : data } }];
